//! Remote companion access: a second, restricted listener for the mobile companion.
//!
//! Security model:
//! - **Disabled by default** (`AppSettings::remote_api_enabled = false`).
//! - **Separate credential**: the remote listener accepts only the remote access token
//!   (`SYMPHONY_REMOTE_TOKEN` in the credential vault, 256 random bits generated by the runtime).
//!   The local per-launch token is not accepted there, and the remote token is not accepted by the
//!   local API.
//! - **Restricted scope**: only the operations listed in [`REMOTE_OPERATIONS`] (monitoring, task
//!   creation/dispatch/cancel/retry, agent approval decisions, scheduler pause/resume) are routed;
//!   everything else — credentials, settings, workflow, diagnostics, project administration,
//!   worktrees, merge approval and remote-access management — answers `403 forbidden_scope`.
//! - **Loopback only**: the listener binds a loopback address. Expose it through a TLS reverse
//!   proxy or an encrypted tunnel; a request a proxy marks as `X-Forwarded-Proto: http` is
//!   refused, so the token is never accepted over a connection known to be cleartext.
//! - **Live lifecycle**: [`RemoteAccessManager::apply`] reconciles the running listener with the
//!   settings (start, stop, rebind) without restarting the runtime. Token rotation and revocation
//!   take effect immediately, including for already-open event streams.
//! - **Explicit CORS**: only the configured origins plus the companion app's own origin; never `*`.

use std::future::Future;
use std::net::{IpAddr, SocketAddr};
use std::path::PathBuf;
use std::pin::Pin;
use std::sync::atomic::{AtomicU16, Ordering};
use std::sync::Arc;
use std::task::{Context, Poll};
use std::time::Duration;

use axum::{
    extract::{MatchedPath, Request},
    http::{Method, StatusCode},
    middleware::Next,
    response::Response,
};
use serde::{Deserialize, Serialize};
use symphony_core::{domain::AppSettings, error::Result};
use symphony_orchestrator::SymphonyOrchestrator;
use tokio::io::{AsyncRead, AsyncWrite, ReadBuf};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{watch, Mutex};
use tracing::{info, warn};
use utoipa::ToSchema;

use crate::{api_error, build_router_inner, generate_access_token, ApiScope, ServerConfig};

/// Vault key of the remote access token.
pub const REMOTE_TOKEN_KEY: &str = "SYMPHONY_REMOTE_TOKEN";

/// Minimum length of a remote access token accepted from the vault.
pub const MIN_REMOTE_TOKEN_LEN: usize = 32;

/// Origin of the Tauri mobile companion's webview; always allowed on the remote listener.
pub const MOBILE_COMPANION_ORIGINS: &[&str] = &["tauri://localhost"];

/// Operations (method, path relative to `/api/v1`) a remote companion may call. Every other
/// documented operation is local-only; `tests/remote_access.rs` asserts the two lists cover the
/// whole OpenAPI document so a new endpoint is never exposed remotely by accident.
pub const REMOTE_OPERATIONS: &[(&str, &str)] = &[
    ("GET", "/health"),
    ("GET", "/runtime"),
    ("GET", "/state"),
    ("POST", "/refresh"),
    ("GET", "/events"),
    ("GET", "/events/recent"),
    ("POST", "/scheduler/pause"),
    ("POST", "/scheduler/resume"),
    ("GET", "/projects"),
    ("GET", "/projects/{id}"),
    ("GET", "/tasks"),
    ("POST", "/tasks"),
    ("GET", "/tasks/{id}"),
    ("POST", "/tasks/{id}/dispatch"),
    ("POST", "/tasks/{id}/cancel"),
    ("POST", "/tasks/{id}/retry"),
    ("GET", "/tasks/{id}/events"),
    ("GET", "/tasks/{id}/attempts"),
    ("GET", "/tasks/{id}/validations"),
    ("GET", "/issues/{issue_identifier}"),
    ("GET", "/approvals"),
    ("POST", "/approvals/{id}/decide"),
    ("GET", "/prs"),
    ("GET", "/prs/{id}"),
    // Undocumented compatibility aliases of `GET /tasks/{id}` and `GET /issues/{..}`.
    ("GET", "/tasks/id/{id}"),
    ("GET", "/{issue_identifier}"),
];

/// Whether a remote client may call `method path` (path relative to `/api/v1`).
pub fn remote_operation_allowed(method: &Method, path: &str) -> bool {
    REMOTE_OPERATIONS
        .iter()
        .any(|(m, p)| *m == method.as_str() && *p == path)
}

/// Route-layer middleware of the remote listener: refuse operations outside the remote scope.
pub(crate) async fn enforce_remote_scope(request: Request, next: Next) -> Response {
    let path = request
        .extensions()
        .get::<MatchedPath>()
        .map(|p| p.as_str().to_string())
        .unwrap_or_default();
    let relative = path.strip_prefix("/api/v1").unwrap_or(&path);
    if !remote_operation_allowed(request.method(), relative) {
        return api_error(
            StatusCode::FORBIDDEN,
            "forbidden_scope",
            "This operation is not available to remote companion clients",
        );
    }
    next.run(request).await
}

/// Middleware of the remote listener: never accept a request that a proxy reports as cleartext.
pub(crate) async fn reject_cleartext_forwarding(request: Request, next: Next) -> Response {
    let cleartext = request
        .headers()
        .get("x-forwarded-proto")
        .and_then(|v| v.to_str().ok())
        .is_some_and(|proto| {
            proto
                .split(',')
                .next()
                .is_some_and(|p| p.trim().eq_ignore_ascii_case("http"))
        });
    if cleartext {
        return api_error(
            StatusCode::FORBIDDEN,
            "insecure_transport",
            "Remote access requires HTTPS; configure the reverse proxy to terminate TLS",
        );
    }
    next.run(request).await
}

/// A bearer token that can be replaced or revoked while servers are running. Event streams
/// subscribe to it and end when it changes.
#[derive(Clone)]
pub struct TokenSlot(Arc<watch::Sender<Option<Arc<String>>>>);

impl TokenSlot {
    pub fn new(token: Option<String>) -> Self {
        Self(Arc::new(watch::Sender::new(token.map(Arc::new))))
    }

    pub fn current(&self) -> Option<Arc<String>> {
        self.0.borrow().clone()
    }

    /// Replace the token; a no-op (no stream is ended) when it is unchanged.
    pub fn set(&self, token: Option<String>) {
        self.0.send_if_modified(|current| {
            let next = token.map(Arc::new);
            if *current == next {
                false
            } else {
                *current = next;
                true
            }
        });
    }

    pub fn subscribe(&self) -> watch::Receiver<Option<Arc<String>>> {
        self.0.subscribe()
    }
}

/// Effective state of the remote listener.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "snake_case")]
pub enum RemoteListenerState {
    /// Remote access is turned off in the settings.
    Disabled,
    /// Enabled, but no remote access token has been generated (or it was revoked).
    TokenMissing,
    /// Listening on `listening_on`.
    Running,
    /// Enabled but not listening; `error` says why (invalid address, port in use, ...).
    Failed,
    /// This runtime host does not manage a remote listener.
    Unavailable,
}

/// Remote access configuration (persisted settings) together with what is actually running.
#[derive(Debug, Clone, Serialize, Deserialize, ToSchema)]
pub struct RemoteAccessStatus {
    /// `remote_api_enabled` from the settings.
    pub enabled: bool,
    pub bind_address: String,
    pub port: u16,
    /// Browser origins allowed in addition to the companion app's own origin.
    pub allowed_origins: Vec<String>,
    /// Whether a remote access token exists. The token itself is never returned here.
    pub token_configured: bool,
    pub state: RemoteListenerState,
    /// Address the listener is bound to while `state` is `running`.
    pub listening_on: Option<String>,
    pub error: Option<String>,
}

/// Response of a token rotation: the new token, shown once.
#[derive(Debug, Clone, Serialize, Deserialize, ToSchema)]
pub struct RemoteTokenIssued {
    /// New remote access token. Store it in the companion app now; it cannot be read back.
    pub token: String,
    pub status: RemoteAccessStatus,
}

/// Is `host` a loopback address (`127.0.0.0/8`, `::1` or `localhost`)?
pub fn is_loopback_host(host: &str) -> bool {
    if host.eq_ignore_ascii_case("localhost") {
        return true;
    }
    host.trim_start_matches('[')
        .trim_end_matches(']')
        .parse::<IpAddr>()
        .is_ok_and(|ip| ip.is_loopback())
}

/// Validate a browser origin for the remote CORS allowlist: `https://host[:port]`, or `http://`
/// for loopback hosts only (development). Wildcards, paths and credentials are rejected.
pub fn validate_remote_origin(origin: &str) -> std::result::Result<(), String> {
    if MOBILE_COMPANION_ORIGINS.contains(&origin) {
        return Ok(());
    }
    if origin.contains('*') {
        return Err(format!("'{origin}': wildcard origins are not allowed"));
    }
    let parsed =
        url::Url::parse(origin).map_err(|_| format!("'{origin}' is not a valid origin"))?;
    let serialized = parsed.origin().ascii_serialization();
    if serialized != origin {
        return Err(format!(
            "'{origin}' must be a bare origin such as https://companion.example.com (no path, \
             query or trailing slash)"
        ));
    }
    let host = parsed.host_str().unwrap_or_default();
    match parsed.scheme() {
        "https" => Ok(()),
        "http" if is_loopback_host(host) => Ok(()),
        "http" => Err(format!(
            "'{origin}' uses http://; remote origins must use https:// (http is allowed only for \
             localhost)"
        )),
        _ => Err(format!("'{origin}' must use https://")),
    }
}

/// Validate the remote-access part of the settings (used by `PUT /settings`).
pub fn validate_remote_settings(settings: &AppSettings) -> std::result::Result<(), String> {
    if !is_loopback_host(settings.remote_bind_address.trim()) {
        return Err(
            "remote_bind_address must be a loopback address (127.0.0.1, ::1 or localhost). Expose \
             the remote API through a TLS reverse proxy or an encrypted tunnel instead of binding \
             it to a network interface"
                .into(),
        );
    }
    for origin in &settings.remote_allowed_origins {
        validate_remote_origin(origin)?;
    }
    Ok(())
}

/// How long [`RemoteAccessManager::stop`] lets open connections finish before closing them.
const GRACEFUL_STOP: Duration = Duration::from_secs(3);

/// A TCP listener whose connections can all be closed at once. axum serves every connection on
/// a task of its own that outlives the accept loop, so stopping the listener alone cannot end a
/// connection whose request is still in flight; [`KillableStream`] can.
struct KillableListener {
    inner: TcpListener,
    kill: watch::Receiver<bool>,
}

impl axum::serve::Listener for KillableListener {
    type Io = KillableStream;
    type Addr = SocketAddr;

    async fn accept(&mut self) -> (Self::Io, Self::Addr) {
        let (stream, addr) = axum::serve::Listener::accept(&mut self.inner).await;
        (KillableStream::new(stream, self.kill.clone()), addr)
    }

    fn local_addr(&self) -> std::io::Result<Self::Addr> {
        self.inner.local_addr()
    }
}

/// A connection that fails every read and write once the listener's kill switch is set, which
/// makes hyper drop the connection (and the request it is serving) immediately.
struct KillableStream {
    inner: TcpStream,
    killed: Pin<Box<dyn Future<Output = ()> + Send>>,
    dead: bool,
}

impl KillableStream {
    fn new(inner: TcpStream, mut kill: watch::Receiver<bool>) -> Self {
        let killed = Box::pin(async move {
            // A dropped sender (manager gone) also ends the connection.
            let _ = kill.wait_for(|killed| *killed).await;
        });
        Self {
            inner,
            killed,
            dead: false,
        }
    }

    /// Whether the kill switch is set; registers the task for wake-up when it is not.
    fn is_dead(&mut self, cx: &mut Context<'_>) -> bool {
        if !self.dead && self.killed.as_mut().poll(cx).is_ready() {
            self.dead = true;
        }
        self.dead
    }
}

fn killed_error() -> std::io::Error {
    std::io::Error::new(
        std::io::ErrorKind::ConnectionAborted,
        "remote listener stopped",
    )
}

impl AsyncRead for KillableStream {
    fn poll_read(
        mut self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        buf: &mut ReadBuf<'_>,
    ) -> Poll<std::io::Result<()>> {
        if self.is_dead(cx) {
            return Poll::Ready(Err(killed_error()));
        }
        Pin::new(&mut self.inner).poll_read(cx, buf)
    }
}

impl AsyncWrite for KillableStream {
    fn poll_write(
        mut self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        buf: &[u8],
    ) -> Poll<std::io::Result<usize>> {
        if self.is_dead(cx) {
            return Poll::Ready(Err(killed_error()));
        }
        Pin::new(&mut self.inner).poll_write(cx, buf)
    }

    fn poll_flush(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<std::io::Result<()>> {
        if self.is_dead(cx) {
            return Poll::Ready(Err(killed_error()));
        }
        Pin::new(&mut self.inner).poll_flush(cx)
    }

    fn poll_shutdown(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<std::io::Result<()>> {
        Pin::new(&mut self.inner).poll_shutdown(cx)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ListenSpec {
    host: String,
    port: u16,
    origins: Vec<String>,
}

struct Running {
    spec: ListenSpec,
    addr: SocketAddr,
    handle: tokio::task::JoinHandle<()>,
    /// Starts axum's graceful shutdown, which closes idle keep-alive connections and waits for
    /// in-flight requests.
    shutdown: tokio::sync::oneshot::Sender<()>,
    /// Closes every open connection at once (see [`KillableStream`]).
    kill: watch::Sender<bool>,
    /// This listener's own copy of the token. Clearing it when the listener stops rejects
    /// further requests on open connections and ends their event streams.
    slot: TokenSlot,
}

struct Inner {
    settings: AppSettings,
    state: RemoteListenerState,
    error: Option<String>,
    running: Option<Running>,
}

/// Owns the remote listener and its token; shared by the desktop host and `symphony-cli`.
pub struct RemoteAccessManager {
    orchestrator: Arc<SymphonyOrchestrator>,
    default_workspace_root: Option<PathBuf>,
    local_port: AtomicU16,
    token: TokenSlot,
    inner: Mutex<Inner>,
}

impl std::fmt::Debug for RemoteAccessManager {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("RemoteAccessManager")
            .field("local_port", &self.local_port.load(Ordering::Relaxed))
            .finish_non_exhaustive()
    }
}

impl RemoteAccessManager {
    pub fn new(
        orchestrator: Arc<SymphonyOrchestrator>,
        default_workspace_root: Option<PathBuf>,
    ) -> Arc<Self> {
        Arc::new(Self {
            orchestrator,
            default_workspace_root,
            local_port: AtomicU16::new(0),
            token: TokenSlot::new(None),
            inner: Mutex::new(Inner {
                settings: AppSettings::default(),
                state: RemoteListenerState::Disabled,
                error: None,
                running: None,
            }),
        })
    }

    /// Port of the local API, which the remote listener must never share.
    pub fn set_local_port(&self, port: u16) {
        self.local_port.store(port, Ordering::Relaxed);
    }

    fn stored_token(&self) -> Option<String> {
        self.orchestrator
            .secret_store()
            .get_vault_secret(REMOTE_TOKEN_KEY)
            .filter(|t| t.len() >= MIN_REMOTE_TOKEN_LEN)
    }

    fn status_of(&self, inner: &Inner) -> RemoteAccessStatus {
        RemoteAccessStatus {
            enabled: inner.settings.remote_api_enabled,
            bind_address: inner.settings.remote_bind_address.clone(),
            port: inner.settings.remote_port,
            allowed_origins: inner.settings.remote_allowed_origins.clone(),
            token_configured: self.token.current().is_some(),
            state: inner.state,
            listening_on: inner.running.as_ref().map(|r| r.addr.to_string()),
            error: inner.error.clone(),
        }
    }

    pub async fn status(&self) -> RemoteAccessStatus {
        let inner = self.inner.lock().await;
        self.status_of(&inner)
    }

    /// Reconcile the listener with `settings`: start, stop or rebind as needed. A listener whose
    /// address and origins are unchanged keeps running (token changes apply in place).
    pub async fn apply(&self, settings: &AppSettings) -> RemoteAccessStatus {
        let mut inner = self.inner.lock().await;
        self.apply_locked(&mut inner, settings).await
    }

    /// `apply` after a settings save: reconciles against the settings persisted *now*, read with
    /// the state lock held, so two concurrent saves can never leave the listener on the older
    /// one. `saved` is used only when the settings cannot be read back.
    pub async fn apply_persisted(&self, saved: &AppSettings) -> RemoteAccessStatus {
        let mut inner = self.inner.lock().await;
        let latest = match self.orchestrator.storage().get_settings().await {
            Ok(latest) => latest,
            Err(err) => {
                warn!(error = %err, "Could not re-read settings; applying the saved copy");
                saved.clone()
            }
        };
        self.apply_locked(&mut inner, &latest).await
    }

    /// Publish `token` to the manager and to the running listener.
    fn set_token(&self, inner: &Inner, token: Option<String>) {
        self.token.set(token.clone());
        if let Some(running) = &inner.running {
            running.slot.set(token);
        }
    }

    /// `apply` with the state lock held, so the vault read and the token publication cannot
    /// interleave with a concurrent rotation or revocation.
    async fn apply_locked(&self, inner: &mut Inner, settings: &AppSettings) -> RemoteAccessStatus {
        let token = self.stored_token();
        self.set_token(inner, token.clone());
        inner.settings = settings.clone();

        let desired: std::result::Result<ListenSpec, (RemoteListenerState, Option<String>)> =
            if !settings.remote_api_enabled {
                Err((RemoteListenerState::Disabled, None))
            } else if token.is_none() {
                Err((
                    RemoteListenerState::TokenMissing,
                    Some("Generate a remote access token to start the remote listener".into()),
                ))
            } else if let Err(msg) = validate_remote_settings(settings) {
                Err((RemoteListenerState::Failed, Some(msg)))
            } else if settings.remote_port == self.local_port.load(Ordering::Relaxed) {
                Err((
                    RemoteListenerState::Failed,
                    Some(format!(
                        "Remote port {} is the local API's port; choose a different port",
                        settings.remote_port
                    )),
                ))
            } else {
                let mut origins: Vec<String> = MOBILE_COMPANION_ORIGINS
                    .iter()
                    .map(|s| s.to_string())
                    .collect();
                for origin in &settings.remote_allowed_origins {
                    if !origins.contains(origin) {
                        origins.push(origin.clone());
                    }
                }
                Ok(ListenSpec {
                    host: settings.remote_bind_address.trim().to_string(),
                    port: settings.remote_port,
                    origins,
                })
            };

        match desired {
            Ok(spec) => {
                if inner.running.as_ref().is_some_and(|r| r.spec == spec) {
                    inner.state = RemoteListenerState::Running;
                    inner.error = None;
                } else {
                    Self::stop(inner).await;
                    match self.bind(spec.clone(), token.clone()).await {
                        Ok(running) => {
                            info!(address = %running.addr, "Remote companion listener started");
                            inner.running = Some(running);
                            inner.state = RemoteListenerState::Running;
                            inner.error = None;
                        }
                        Err(err) => {
                            warn!(error = %err, "Remote companion listener failed to start");
                            inner.state = RemoteListenerState::Failed;
                            inner.error = Some(format!(
                                "Could not listen on {}:{}: {err}",
                                spec.host, spec.port
                            ));
                        }
                    }
                }
            }
            Err((state, error)) => {
                Self::stop(inner).await;
                inner.state = state;
                inner.error = error;
            }
        }
        self.status_of(inner)
    }

    async fn bind(&self, spec: ListenSpec, token: Option<String>) -> std::io::Result<Running> {
        let slot = TokenSlot::new(token);
        let config = ServerConfig {
            bind_host: spec.host.clone(),
            port: spec.port,
            access_token: None,
            allowed_origins: spec.origins.clone(),
            default_workspace_root: self.default_workspace_root.clone(),
            scope: ApiScope::Remote,
            remote_access: None,
            backup_root: None,
        };
        let router = build_router_inner(self.orchestrator.clone(), &config, Some(slot.clone()));
        let host = spec.host.trim_start_matches('[').trim_end_matches(']');
        let listener = TcpListener::bind((host, spec.port)).await?;
        let addr = listener.local_addr()?;
        let (kill, kill_rx) = watch::channel(false);
        let listener = KillableListener {
            inner: listener,
            kill: kill_rx,
        };
        let (shutdown, signal) = tokio::sync::oneshot::channel::<()>();
        let handle = tokio::spawn(async move {
            let served = axum::serve(listener, router).with_graceful_shutdown(async move {
                let _ = signal.await;
            });
            if let Err(err) = served.await {
                tracing::error!(error = %err, "Remote companion listener terminated with error");
            }
        });
        Ok(Running {
            spec,
            addr,
            handle,
            shutdown,
            kill,
            slot,
        })
    }

    /// Stop the listener and close its connections: the token is cleared first (requests on
    /// open connections are rejected and event streams end), then a graceful shutdown closes
    /// the connections; connections still open after a short grace period (a request still in
    /// flight) are closed forcibly, which also lets the graceful shutdown complete.
    async fn stop(inner: &mut Inner) {
        if let Some(mut running) = inner.running.take() {
            running.slot.set(None);
            let _ = running.shutdown.send(());
            if tokio::time::timeout(GRACEFUL_STOP, &mut running.handle)
                .await
                .is_err()
            {
                warn!(address = %running.addr, "Closing remote connections still open after the grace period");
                let _ = running.kill.send(true);
                if tokio::time::timeout(GRACEFUL_STOP, &mut running.handle)
                    .await
                    .is_err()
                {
                    running.handle.abort();
                    let _ = running.handle.await;
                }
            }
            info!(address = %running.addr, "Remote companion listener stopped");
        }
    }

    /// Generate a new random token, store it in the vault and apply it immediately. The previous
    /// token stops working at once.
    pub async fn rotate_token(&self) -> Result<RemoteTokenIssued> {
        let mut inner = self.inner.lock().await;
        // Load the settings first: once the new token is stored the caller must always receive
        // it, so nothing that can fail runs after the vault write.
        let settings = self.orchestrator.storage().get_settings().await?;
        let token = generate_access_token();
        let previous = self.stored_token();
        self.orchestrator
            .secret_store()
            .set_secret(REMOTE_TOKEN_KEY, &token)?;
        // The previous token stops working now, so it no longer needs masking in logs (unless
        // another source, e.g. a credential or environment variable, holds the same value).
        self.set_token(&inner, Some(token.clone()));
        if let Some(previous) = previous {
            symphony_core::redaction::forget_secret(&previous);
        }
        let status = self.apply_locked(&mut inner, &settings).await;
        info!("Remote access token rotated");
        Ok(RemoteTokenIssued { token, status })
    }

    /// Delete the token and stop the listener; remote clients are disconnected immediately.
    pub async fn revoke_token(&self) -> Result<RemoteAccessStatus> {
        let mut inner = self.inner.lock().await;
        let settings = self.orchestrator.storage().get_settings().await?;
        let previous = self.stored_token();
        self.orchestrator
            .secret_store()
            .delete_secret(REMOTE_TOKEN_KEY)?;
        // Every remote request is rejected from here on (an absent token rejects all requests).
        self.set_token(&inner, None);
        if let Some(previous) = previous {
            symphony_core::redaction::forget_secret(&previous);
        }
        let status = self.apply_locked(&mut inner, &settings).await;
        info!("Remote access token revoked");
        Ok(status)
    }

    /// Stop the listener (runtime shutdown).
    pub async fn shutdown(&self) {
        let mut inner = self.inner.lock().await;
        Self::stop(&mut inner).await;
        inner.state = RemoteListenerState::Disabled;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn loopback_detection() {
        for host in [
            "127.0.0.1",
            "127.1.2.3",
            "::1",
            "[::1]",
            "localhost",
            "LOCALHOST",
        ] {
            assert!(is_loopback_host(host), "{host}");
        }
        for host in ["0.0.0.0", "192.168.1.10", "::", "example.com", ""] {
            assert!(!is_loopback_host(host), "{host}");
        }
    }

    #[test]
    fn origin_validation() {
        for ok in [
            "https://companion.example.com",
            "https://companion.example.com:8443",
            "http://localhost:1421",
            "http://127.0.0.1:1421",
            "tauri://localhost",
        ] {
            assert!(validate_remote_origin(ok).is_ok(), "{ok}");
        }
        for bad in [
            "*",
            "https://*.example.com",
            "http://192.168.1.5:1421",
            "https://example.com/",
            "https://example.com/app",
            "https://user:pw@example.com",
            "ftp://example.com",
            "null",
        ] {
            assert!(validate_remote_origin(bad).is_err(), "{bad}");
        }
    }

    #[test]
    fn remote_scope_excludes_administration() {
        assert!(remote_operation_allowed(&Method::POST, "/tasks"));
        assert!(remote_operation_allowed(
            &Method::POST,
            "/approvals/{id}/decide"
        ));
        for (method, path) in [
            (Method::GET, "/credentials"),
            (Method::POST, "/credentials"),
            (Method::DELETE, "/credentials/{key}"),
            (Method::GET, "/workflow"),
            (Method::PUT, "/workflow"),
            (Method::PUT, "/settings"),
            (Method::GET, "/settings"),
            (Method::GET, "/diagnostics/export"),
            (Method::POST, "/projects"),
            (Method::DELETE, "/projects/{id}"),
            (Method::POST, "/prs/{id}/approve-merge"),
            (Method::GET, "/remote-access"),
            (Method::POST, "/remote-access/token"),
        ] {
            assert!(!remote_operation_allowed(&method, path), "{method} {path}");
        }
    }

    #[test]
    fn token_slot_notifies_only_on_change() {
        let slot = TokenSlot::new(Some("a".repeat(40)));
        let mut rx = slot.subscribe();
        rx.mark_unchanged();
        slot.set(Some("a".repeat(40)));
        assert!(!rx.has_changed().unwrap());
        slot.set(None);
        assert!(rx.has_changed().unwrap());
        assert!(slot.current().is_none());
    }
}
